CREATE TABLE task_blocks (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), task_id UUID NOT NULL, block_type VARCHAR(30) NOT NULL, content TEXT, position INTEGER NOT NULL DEFAULT 0, created_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP WITH TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_task_blocks_task FOREIGN KEY (task_id) REFERENCES tasks(id) ON DELETE CASCADE); CREATE INDEX idx_task_blocks_task_id ON task_blocks(task_id); CREATE INDEX idx_task_blocks_task_position ON task_blocks(task_id, position);
